48 #pragma once
49 #ifndef INCLUDED_TINY_FORMATTER_H
50 #define INCLUDED_TINY_FORMATTER_H
51 
52 #ifdef __GNUC__
53 #   pragma GCC system_header
54 #endif
55 
56 #include <sstream>
57 
58 namespace Assimp {
59 namespace Formatter {
60 
61 // ------------------------------------------------------------------------------------------------
71 template < typename T,
72     typename CharTraits = std::char_traits<T>,
73     typename Allocator  = std::allocator<T> >
74 class basic_formatter {
75 public:
76     typedef class std::basic_string<T,CharTraits,Allocator> string;
77     typedef class std::basic_ostringstream<T,CharTraits,Allocator> stringstream;
78 
79     basic_formatter() {
80         // empty
81     }
82 
83     /* Allow basic_formatter<T>'s to be used almost interchangeably
84      * with std::(w)string or const (w)char* arguments because the
85      * conversion c'tor is called implicitly. */
86     template <typename TT>
87     basic_formatter(const TT& sin)  {
88         underlying << sin;
89     }
90 
91     // Same problem as the copy constructor below, but with root cause is that stream move
92     // is not permitted on older GCC versions. Small performance impact on those platforms.
93 #if defined(__GNUC__) && (__GNUC__ == 4 && __GNUC_MINOR__ <= 9)
94     basic_formatter(basic_formatter&& other) {
95         underlying << (string)other;
96     }
97 #else
98     basic_formatter(basic_formatter&& other)
99         : underlying(std::move(other.underlying)) {
100     }
101 #endif
102 
103     // The problem described here:
104     // https://sourceforge.net/tracker/?func=detail&atid=1067632&aid=3358562&group_id=226462
105     // can also cause trouble here. Apparently, older gcc versions sometimes copy temporaries
106     // being bound to const ref& function parameters. Copying streams is not permitted, though.
107     // This workaround avoids this by manually specifying a copy ctor.
108 #if !defined(__GNUC__) || !defined(__APPLE__) || __GNUC__ > 4 || (__GNUC__ == 4 && __GNUC_MINOR__ >= 6)
109     explicit basic_formatter(const basic_formatter& other) {
110         underlying << (string)other;
111     }
112 #endif
113 
114     operator string () const {
115         return underlying.str();
116     }
117 
118     /* note - this is declared const because binding temporaries does only
119      * work for const references, so many function prototypes will
120      * include const basic_formatter<T>& s but might still want to
121      * modify the formatted string without the need for a full copy.*/
122     template <typename TToken, typename std::enable_if<!std::is_base_of<std::exception, TToken>::value>::type * = nullptr>
123     const basic_formatter &operator<<(const TToken &s) const {
124         underlying << s;
125         return *this;
126     }
127 
128     template <typename TToken, typename std::enable_if<std::is_base_of<std::exception, TToken>::value>::type * = nullptr>
129     const basic_formatter &operator<<(const TToken &s) const {
130         underlying << s.what();
131         return *this;
132     }
133 
134     template <typename TToken, typename std::enable_if<!std::is_base_of<std::exception, TToken>::value>::type * = nullptr>
135     basic_formatter &operator<<(const TToken &s) {
136         underlying << s;
137         return *this;
138     }
139 
140     template <typename TToken, typename std::enable_if<std::is_base_of<std::exception, TToken>::value>::type * = nullptr>
141     basic_formatter &operator<<(const TToken &s) {
142         underlying << s.what();
143         return *this;
144     }
145 
146 
147     // comma operator overloaded as well, choose your preferred way.
148     template <typename TToken>
149     const basic_formatter& operator, (const TToken& s) const {
150         *this << s;
151         return *this;
152     }
153 
154     template <typename TToken>
155     basic_formatter& operator, (const TToken& s) {
156         *this << s;
157         return *this;
158     }
159 
160     // Fix for MSVC8
161     // See https://sourceforge.net/projects/assimp/forums/forum/817654/topic/4372824
162     template <typename TToken>
163     basic_formatter& operator, (TToken& s) {
164         *this << s;
165         return *this;
166     }
167 
168 
169 private:
170     mutable stringstream underlying;
171 };
172 
173 
174 typedef basic_formatter< char > format;
175 typedef basic_formatter< wchar_t > wformat;
176 
177 } // ! namespace Formatter
178 
179 } // ! namespace Assimp
180 
181 #endif
